const api=(url:string,options?:RequestInit)=>withAuthRetry(async()=>{const response=await fetch(url,{credentials:'include',cache:'no-store',...options});const result=await response.json();if(!response.ok||result.ok===false)throw new Error(result.message||'No se pudo completar la solicitud.');return result})
const money=(cents:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100)
const uid=(prefix:string)=>`${prefix}-${crypto.randomUUID()}`

function LoginPanel({onLogin,lang,setLang}:{onLogin:(user:User)=>Promise<void>;lang:Language;setLang:(v:Language)=>void}){
  const rememberedEmail=localStorage.getItem('webfactory-client-remember-email')||''
  const [email,setEmail]=useState(rememberedEmail);const [password,setPassword]=useState('');const [showPassword,setShowPassword]=useState(false);const [rememberMe,setRememberMe]=useState(Boolean(rememberedEmail));const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [sent,setSent]=useState(false)
  const submit=async(event:FormEvent)=>{event.preventDefault();setBusy(true);setError('');try{if(rememberMe)localStorage.setItem('webfactory-client-remember-email',email.trim());else localStorage.removeItem('webfactory-client-remember-email');const current=await login(email,password);await onLogin(current)}catch{setError(lang==='es'?'No se pudo iniciar sesión. Revisa tus datos o inténtalo más tarde.':'Could not sign in. Check your details or try again later.')}finally{setBusy(false)}}
  const recover=async()=>{if(!email)return setError(lang==='es'?'Escribe primero tu email.':'Enter your email first.');setBusy(true);setError('');try{await requestPasswordRecovery(email);setSent(true)}catch{setSent(true)}finally{setBusy(false)}}
  const t=portalCopy[lang];return <section className="ca-login"><div className="portal-language"><button className={lang==='en'?'active':''} onClick={()=>setLang('en')}>EN</button><button className={lang==='es'?'active':''} onClick={()=>setLang('es')}>ES</button><ThemeToggle/></div><a className="portal-return-home" href="/"><span aria-hidden="true">←</span> {lang==='es'?'Volver a WebFactory PR':'Return to WebFactory PR'}</a><AdaptiveLogo alt="WebFactory PR"/><small>{t.private}</small><h1>{t.title}</h1><p>{t.text}</p><form onSubmit={submit}><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label><label>{t.password}<span className="portal-password-field"><input type={showPassword?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/><button type="button" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?(lang==='es'?'Ocultar contraseña':'Hide password'):(lang==='es'?'Ver contraseña':'View password')}>{showPassword?(lang==='es'?'Ocultar':'Hide'):(lang==='es'?'Ver':'View')}</button></span></label><label className="portal-remember"><input type="checkbox" checked={rememberMe} onChange={e=>setRememberMe(e.target.checked)}/><span>{lang==='es'?'Recordarme':'Remember me'}</span></label><button disabled={busy}>{busy?t.checking:t.enter}</button></form><button className="ca-link" disabled={busy} onClick={recover}>{t.forgot}</button>{sent&&<div className="ca-success">{t.sent}</div>}{error&&<div className="ca-error">{error}</div>}</section>
}

export default function ClientAdminPage(){
  const [emailPreview,setEmailPreview]=useState('');
  const [menuOpen,setMenuOpen]=useState(false);const [lang,setLang]=useState<Language>('en');const [user,setUser]=useState<User|null>(null);const [loading,setLoading]=useState(true);const [resetToken,setResetToken]=useState('');const [inviteToken,setInviteToken]=useState('');const [newPassword,setNewPassword]=useState('');const [authMessage,setAuthMessage]=useState('')
  const [sites,setSites]=useState<Array<{siteId:string;slug:string;businessName:string;status:string}>>([]);const [site,setSite]=useState<ClientSite|null>(null);const [membership,setMembership]=useState<any>(null);const [tab,setTab]=useState<Tab>('overview');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');const [commerce,setCommerce]=useState<{orders:Transaction[];bookings:Transaction[]}>({orders:[],bookings:[]});const [calendars,setCalendars]=useState<Array<{id:string;summary:string;primary:boolean}>>([]);const [googleConfigured,setGoogleConfigured]=useState(false);const [billing,setBilling]=useState<BillingInfo|null>(null)

  const appearance=usePortalAppearance(user?.id)
  const openSite=async(siteId:string,returnToIntegrations=false)=>{if(!confirmLeaveDrafts())return;const detail=await api(`/.netlify/functions/client-admin?siteId=${encodeURIComponent(siteId)}`);setSite(detail.site);setMembership(detail.membership||null);let remembered:Tab='overview';try{const candidate=sessionStorage.getItem('wf-section:'+siteId) as Tab;const safe=['overview','website','catalog','team','locations','orders','bookings','customers','analytics','settings'];const capability=candidate==='team'||candidate==='locations'?'employees':candidate;if(safe.includes(candidate)&&(!detail.membership?.capabilities||detail.membership.capabilities.includes(capability)))remembered=candidate}catch{}setTab(returnToIntegrations?'integrations':remembered);setMessage('');setError('')}
  const loadSites=async()=>{const result=await api('/.netlify/functions/client-admin');setSites(result.sites);if(result.sites.length){const returnParams=new URLSearchParams(location.search);const returnSite=returnParams.get('siteId');const integrationReturn=returnParams.has('stripe')||returnParams.has('google')||returnParams.has('businessEmail');const preferred=returnSite&&result.sites.some((entry:any)=>entry.siteId===returnSite)?returnSite:site&&result.sites.some((entry:any)=>entry.siteId===site.siteId)?site.siteId:result.sites[0].siteId;await openSite(preferred,integrationReturn);if(integrationReturn)history.replaceState({},'',location.pathname)}else{setSite(null);setMembership(null)}}
  useEffect(()=>{document.documentElement.lang=lang},[lang])
  useEffect(()=>{document.title='Portal administrativo | WebFactory PR';let unsub=()=>{};(async()=>{try{const callback=await handleAuthCallback();if(callback?.type==='recovery'){setResetToken('recovery');return}if(callback?.type==='invite'&&callback.token){setInviteToken(callback.token);return}const current=callback?.user||await getUser();setUser(current);if(current)await loadSites()}catch(e){setError(e instanceof Error?e.message:'No se pudo abrir el portal.')}finally{setLoading(false)}})();unsub=onAuthChange((_event,current)=>{setUser(current);if(!current){setSite(null);setSites([]);setMembership(null);setCommerce({orders:[],bookings:[]});setBilling(null);setCalendars([]);setTab('overview');setError('');setMessage('')}else if(_event==='login_remote'){void loadSites().catch(()=>setError('Unable to refresh business access.'))}});return()=>unsub()},[])
  const save=async(section:string,value:unknown)=>{if(!site||busy)return;setBusy(true);setError('');setMessage('');try{const result=await api('/.netlify/functions/client-admin',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({siteId:site.siteId,section,value,revision:site.revision})});setSite(result.site);setMessage(lang==='es'?'Cambios publicados en tiempo real.':'Changes published in real time.');feedback.success()}catch(e){setError(e instanceof Error?e.message:(lang==='es'?'No se pudo guardar.':'The changes could not be saved.'));feedback.error()}finally{setBusy(false)}}
  const loadCommerce=async()=>{if(!site)return;const result=await api(`/.netlify/functions/client-commerce-admin?siteId=${encodeURIComponent(site.siteId)}`);setCommerce({orders:result.orders,bookings:result.bookings})}
  const loadCalendar=async()=>{if(!site)return;const result=await api(`/.netlify/functions/google-calendar-status?siteId=${encodeURIComponent(site.siteId)}`);setCalendars(result.calendars||[]);setGoogleConfigured(result.configured);if(result.message)setError(result.message)}
  const loadBilling=async()=>{if(!site)return;const result=await api(`/.netlify/functions/subscription-readiness?siteId=${encodeURIComponent(site.siteId)}`);setBilling(result)}
  useEffect(()=>{if(['overview','orders','bookings','analytics','kitchen'].includes(tab))loadCommerce().catch(e=>setError(e.message));if(tab==='integrations')loadCalendar().catch(e=>setError(e.message));if(tab==='billing')loadBilling().catch(e=>setError(e.message))},[tab,site?.siteId])
  useEffect(()=>{if(tab!=='kitchen'||!user)return;let pending=false;const refresh=async()=>{if(pending||document.visibilityState!=='visible')return;pending=true;try{await loadCommerce()}catch{}finally{pending=false}};const timer=window.setInterval(refresh,4000);return()=>window.clearInterval(timer)},[tab,site?.siteId,user])
  const resetPassword=async()=>{const es=lang==='es';if(newPassword.length<15)return setError(es?'Usa una contraseña de al menos 15 caracteres.':'Use a password of at least 15 characters.');setBusy(true);try{let current:User|null;if(inviteToken){const invited=await acceptInvite(inviteToken,newPassword);if(!invited.email)throw new Error(es?'La invitación no contiene un email válido.':'The invitation does not contain a valid email.');current=invited}else{current=await updateUser({password:newPassword})}setResetToken('');setInviteToken('');setAuthMessage(es?'Contraseña guardada.':'Password saved.');setUser(current);if(current)await loadSites()}catch(e){setError(e instanceof Error?e.message:(es?'No se pudo guardar la contraseña.':'The password could not be saved.'))}finally{setBusy(false)}}
  const signOut=async()=>{if(!confirmLeaveDrafts())return;try{await logout();setUser(null);setSite(null);setSites([]);setMembership(null);setCommerce({orders:[],bookings:[]});setBilling(null);setCalendars([]);setTab('overview');setError('');setMessage('')}catch{setError(lang==='es'?'No se pudo confirmar el cierre de sesión. Inténtalo de nuevo.':'Sign out could not be confirmed. Please try again.')}}
  const transactionAction=async(record:Transaction,action:string)=>{if(!site)return;const es=lang==='es';const [actionName,kitchenStatus]=action.split(':');const payload:any={siteId:site.siteId,kind:record.kind,transactionId:record.transactionId,action:actionName,...(kitchenStatus?{kitchenStatus}:{})};if(actionName==='preview_confirmation'){setBusy(true);try{const result=await api('/.netlify/functions/client-commerce-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});setEmailPreview(result.html)}catch(e){setError(e instanceof Error?e.message:'Could not load confirmation.')}finally{setBusy(false)}return}if(actionName==='refund'){const remaining=Math.max(0,Number(record.amountTotal||0)-Number(record.refundedAmount||0));const amountText=prompt(es?`Monto a reembolsar (máximo ${money(remaining)}):`:`Refund amount (maximum ${money(remaining)}):`,(remaining/100).toFixed(2));if(amountText===null)return;const amount=Number(amountText);if(!Number.isFinite(amount)||amount<=0||Math.round(amount*100)>remaining){setError(es?'El monto del reembolso no es válido.':'The refund amount is invalid.');feedback.warning();return}const reason=prompt(es?'Motivo del reembolso (opcional):':'Refund reason (optional):','')??'';payload.amount=amount;payload.reason=reason;}else if(actionName==='mark_paid'&&record.kind==='order'&&!confirm(es?'¿Confirmaste que recibiste el pago de esta orden? Se registrará el pago y se completarán sus registros pendientes; no vuelvas a cobrar si ya pagó.':'Have you confirmed receipt of payment for this order? Its payment and pending records will be completed; do not collect again if already paid.'))return;else if(actionName==='cancel_in_person'&&!confirm(es?'¿Cancelar esta orden sin cobrar y liberar sus unidades reservadas?':'Cancel this unpaid order and release its reserved units?'))return;else if(actionName==='recover_pos'&&!confirm(es?'¿Confirmaste el pago presencial y deseas recuperar los registros de esta misma venta sin cobrar ni reenviar correos?':'Have you confirmed the in-person payment and want to recover this same sale without charging or resending emails?'))return;else if(actionName==='recover_ath'&&!confirm(es?'¿Volver a verificar este pago con ATH y completar sus registros pendientes sin reenviar correos?':'Verify this payment with ATH again and complete pending records without resending emails?'))return;else if(!['recover_ath','recover_pos','cancel_in_person',...(record.kind==='order'?['mark_paid']:[])].includes(actionName)&&!['kitchen_status','sync_calendar','invite_customer'].includes(actionName)&&!confirm(es?`¿Confirmas ${actionName} para ${record.transactionId}?`:`Confirm ${actionName} for ${record.transactionId}?`))return;setBusy(true);try{await api('/.netlify/functions/client-commerce-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadCommerce();setMessage(es?'Transacción actualizada.':'Transaction updated.');feedback.success()}catch(e){setError(e instanceof Error?e.message:(es?'No se pudo actualizar.':'The transaction could not be updated.'));feedback.error()}finally{setBusy(false)}}

  if(loading)return <main className="ca-page"><div className="ca-loading">{lang==='es'?'Abriendo portal seguro…':'Opening secure portal…'}</div></main>
  if(resetToken||inviteToken)return <main className="ca-page"><section className="ca-login"><div className="portal-language"><button className={lang==='en'?'active':''} onClick={()=>setLang('en')}>EN</button><button className={lang==='es'?'active':''} onClick={()=>setLang('es')}>ES</button><ThemeToggle/></div><a className="portal-return-home" href="/"><span aria-hidden="true">←</span> {lang==='es'?'Volver a WebFactory PR':'Return to WebFactory PR'}</a><AdaptiveLogo alt="WebFactory PR"/><h1>{lang==='es'?'Establece tu contraseña':'Set your password'}</h1><label>{lang==='es'?'Nueva contraseña':'New password'}<input type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)}/></label><button onClick={resetPassword} disabled={busy}>{lang==='es'?'Guardar contraseña':'Save password'}</button>{error&&<div className="ca-error">{error}</div>}</section></main>
  if(!user)return <main className="ca-page"><LoginPanel lang={lang} setLang={setLang} onLogin={async current=>{setUser(current);await loadSites()}}/></main>
  if(!site)return <main className="ca-page"><header className="ca-top"><a className="portal-return-home" href="/"><span aria-hidden="true">←</span> {lang==='es'?'Volver a WebFactory PR':'Return to WebFactory PR'}</a><AdaptiveLogo alt="WebFactory PR"/><button onClick={signOut}>{lang==='es'?'Salir':'Sign out'}</button></header><section className="ca-empty"><h1>{lang==='es'?'No hay negocios asignados.':'No businesses are assigned.'}</h1><p>{lang==='es'?'Completa el Builder con este mismo email para crear tu website y activar los 7 días gratis.':'Complete the Builder with this same email to create your website and activate the free 7-day trial.'}</p><a className="ca-primary-link" href="/builder">{lang==='es'?'Abrir Builder':'Open Builder'}</a></section></main>

  const publicUrl=`/sites/${site.slug}`;const t=portalCopy[lang];const displayBusinessName=lang==='es'?(site.business.nameEs||site.business.nameEn||site.business.name):(site.business.nameEn||site.business.name||site.business.nameEs||'')
  const accentColor = appearance.accent
  const isFoodBusiness=Boolean(site.business.category&&/restaurant|food|catering|bakery|cafe|coffee|comida|alimento|panader|cafeter|restaurante/i.test(`${site.business.category||''} ${site.business.name||''}`))
  const allowedNav=(items:Array<[Tab,string]>)=>items.filter(([id])=>id==='training'||id==='security'||id==='appearance'||!membership?.capabilities||membership.capabilities.includes(id==='team'||id==='locations'?'employees':id==='redesign'?'website':id==='inventory'?'catalog':id))
  const navGroups=[
    {title:lang==='es'?'Principal':'Home',items:allowedNav([['overview',t.overview],['training',t.training]])},
    {title:lang==='es'?'Tu página':'Your website',items:allowedNav([['website',lang==='es'?'Editar página':'Edit website'],['redesign',lang==='es'?'Cambiar diseño':'Change design'],['share',lang==='es'?'Compartir página':'Share website']])},
    {title:lang==='es'?'Ventas y citas':'Sales and bookings',items:allowedNav([...(isFoodBusiness?[['kitchen',lang==='es'?'Preparar órdenes':'Prepare orders'] as [Tab,string]]:[]),['orders',lang==='es'?'Ver órdenes':'View orders'],['bookings',lang==='es'?'Ver citas':'View appointments'],['customers',lang==='es'?'Ver clientes':'View customers']])},
    {title:lang==='es'?'Negocio':'Business',items:allowedNav([['catalog',lang==='es'?'Productos y servicios':'Products and services'],['inventory',lang==='es'?'Inventario':'Inventory'],['team',lang==='es'?'Empleados':'Employees'],['locations',lang==='es'?'Sucursales':'Locations'],['pos','POS'],['payments',lang==='es'?'Cobros y pagos':'Payments'],['marketing',lang==='es'?'Promoción y reseñas':'Marketing and reviews'],['analytics',lang==='es'?'Resultados':'Business results']])},
    {title:lang==='es'?'Cuenta y ajustes':'Account and settings',items:allowedNav([['appearance',lang==='es'?'Apariencia y preferencias':'Appearance and preferences'],['security',lang==='es'?'Seguridad de mi cuenta':'Account security'],['integrations',lang==='es'?'Conexiones':'Connected apps'],['settings',lang==='es'?'Ajustes del negocio':'Business settings'],['billing',lang==='es'?'Plan y pagos WebFactory':'WebFactory plan']])}
  ].filter(group=>group.items.length)
  return <PortalPanelProvider lang={lang}><main className="ca-dashboard" data-portal-palette={appearance.paletteMode} style={{...(appearance.paletteMode==='custom'?portalPalette(accentColor,appearance.theme):{}),'--portal-accent':accentColor,'--portal-accent-text':contrastTextColor(accentColor),'--ca-primary':'#0B1529','--ca-accent':accentColor,'--ca-accent-text':contrastTextColor(accentColor)} as React.CSSProperties}>
    <aside className={`ca-sidebar${menuOpen?' ca-menu-open':''}`}><div className="ca-brand-row"><AdaptiveLogo alt="WebFactory PR" variant={appearance.paletteMode==='original'||appearance.theme==='dark'?'dark':'light'}/><div className="portal-language sidebar"><button className={lang==='en'?'active':''} onClick={()=>setLang('en')}>EN</button><button className={lang==='es'?'active':''} onClick={()=>setLang('es')}>ES</button><ThemeToggle/></div></div><div className="ca-business-id"><small>{lang==='es'?'NEGOCIO':'BUSINESS'}</small><strong>{displayBusinessName}</strong><span>{user.email}</span>{sites.length>1&&<label className="ca-site-switcher"><span>{lang==='es'?'Cambiar página':'Switch page'}</span><select value={site.siteId} onChange={e=>openSite(e.target.value).catch(err=>setError(err instanceof Error?err.message:String(err)))}>{sites.map(entry=><option value={entry.siteId} key={entry.siteId}>{entry.businessName||entry.slug}</option>)}</select></label>}</div><FeedbackPreferences lang={lang}/><button className="ca-mobile-menu-toggle" aria-expanded={menuOpen} aria-controls="ca-business-menu" onClick={()=>setMenuOpen(v=>!v)}>{menuOpen?(lang==='es'?'Cerrar menú':'Close menu'):(lang==='es'?'Menú del negocio':'Business menu')} <span aria-hidden="true">{menuOpen?'−':'+'}</span></button><nav id="ca-business-menu" className="ca-nav-groups" aria-label={lang==='es'?'Menú del negocio':'Business menu'}>{navGroups.map((group,index)=><details key={group.title} open={group.items.some(([id])=>id===tab)||index===0}><summary>{group.title}</summary>{group.items.map(([id,label])=><button key={id} className={tab===id?'active':''} aria-current={tab===id?'page':undefined} onClick={()=>{if(id!==tab&&!confirmLeaveDrafts())return;setTab(id);try{sessionStorage.setItem('wf-section:'+site.siteId,id)}catch{}setMenuOpen(false);setMessage('');setError('')}}>{label}</button>)}</details>)}</nav><a href={publicUrl} target="_blank" rel="noreferrer">{lang==='es'?'Ver mi página ↗':'View my website ↗'}</a><button className="ca-signout" onClick={signOut}>{lang==='es'?'Salir':'Sign out'}</button></aside>
    <section className="ca-work">{emailPreview&&<PortalPanel className="ca-panel"><header><h2>{lang==='es'?'Vista previa de confirmación':'Confirmation preview'}</h2><p>{lang==='es'?'Esta vista no envía correos ni modifica la reservación.':'This preview does not send email or change the booking.'}</p></header><button onClick={()=>setEmailPreview('')}>{lang==='es'?'Cerrar vista previa':'Close preview'}</button><iframe title={lang==='es'?'Correo de confirmación':'Booking confirmation email'} srcDoc={emailPreview} sandbox="" referrerPolicy="no-referrer" style={{width:'100%',height:900,border:'none',marginTop:16,borderRadius:16}}/></PortalPanel>}<header><div><small>{lang==='es'?'MI NEGOCIO':'MY BUSINESS'}</small><h1>{displayBusinessName}</h1></div><div><span className={`ca-status ${site.status}`}>{site.status.replaceAll('_',' ')}</span></div></header>{message&&<div className="ca-success" role="status">{message}</div>}{error&&<div className="ca-error" role="alert">{error}</div>}{tab!=='overview'&&portalHelp[lang][tab]&&<aside className="ca-help-card" aria-live="polite"><span aria-hidden="true">💡</span><div><h2>{portalHelp[lang][tab]!.title}</h2><p>{portalHelp[lang][tab]!.description}</p><small>{portalHelp[lang][tab]!.tip}</small></div></aside>}
      {tab==='training'&&<PortalTraining lang={lang} onExit={()=>setTab('overview')}/>}
      {tab==='overview'&&<><BusinessControlCenter site={site} commerce={commerce} lang={lang} onNavigate={id=>{if(confirmLeaveDrafts())setTab(id as Tab)}} canNavigate={id=>navGroups.some(group=>group.items.some(([tab])=>tab===id))}/><Overview site={site} commerce={commerce} lang={lang} onSave={value=>save('business',value)} busy={busy}/></>}
      {tab==='website'&&<><WebsitePanel site={site} lang={lang}/><WebsiteEditor site={site} lang={lang} busy={busy} onSave={value=>save('business',value)}/><HoursEditor site={site} setSite={setSite} lang={lang} onSave={()=>save('hours',site.hours)} busy={busy}/></>}
      {tab==='redesign'&&<Panel title={lang==='es'?'Cambiar diseño':'Change design'} text=""><a href={`/builder?edit=${encodeURIComponent(site.siteId)}`}>{lang==='es'?'Abrir Builder de esta página':'Open Builder for this page'}</a></Panel>}
      {tab==='share'&&<BusinessQrPanel preview={site.previewQr} siteId={site.siteId} slug={site.slug} businessName={site.business?.name||site.business?.nameEn||site.slug} lang={lang} revision={site.revision} accent={site.design?.secondary||site.design?.primary||'#3C86F6'}/>}
      {tab==='kitchen'&&<KitchenPanel records={commerce.orders} lang={lang} busy={busy} locations={site.business.locations||[]} timeZone={site.settings?.timezone||'America/Puerto_Rico'} onStatus={(record,status)=>transactionAction(record,`kitchen_status:${status}`)}/>}
      {tab==='orders'&&<TransactionPanel records={commerce.orders} kind="order" lang={lang} onAction={transactionAction} busy={busy}/>}
      {tab==='bookings'&&<><BookingCalendar records={commerce.bookings} lang={lang} timeZone={site.settings?.timezone} employees={site.employees}/><TransactionPanel records={commerce.bookings} kind="booking" lang={lang} timeZone={site.settings?.timezone} googleConnected={site.googleCalendar?.connected} employees={site.employees} onAction={transactionAction} busy={busy}/></>}
      {tab==='customers'&&<CustomersPanel siteId={site.siteId} lang={lang}/>}
      {tab==='inventory'&&<><Panel title={lang==='es'?'Existencias y consumo':'Stock and consumption'} text={lang==='es'?'Registra productos en Catálogo y activa su control de existencias. Los ajustes cambian unidades; los costos de materiales se registran por separado en Resultados. No se descuentan materiales automáticamente por servicio.':'Add products in Catalog and enable stock tracking. Adjustments change units; material costs are recorded separately in Business results. Materials are not deducted automatically per service.'} children={null}/><InventoryStatusPanel site={site} lang={lang}/><InventoryAdjustmentPanel site={site} setSite={setSite} lang={lang}/><InventoryMovementsPanel siteId={site.siteId} lang={lang}/></>}
      {tab==='catalog'&&<><CatalogEditor site={site} setSite={setSite} lang={lang} onSave={()=>save('catalog',site.catalog)} busy={busy}/><InventoryStatusPanel site={site} lang={lang}/><InventoryAdjustmentPanel site={site} setSite={setSite} lang={lang}/><InventoryMovementsPanel siteId={site.siteId} lang={lang}/></>}
      {tab==='team'&&<>{['owner','admin'].includes(membership?.role)&&<BusinessAccountingPanel siteId={site.siteId} employees={site.employees} catalog={site.catalog} lang={lang}/>}<TeamEditor site={site} setSite={setSite} lang={lang} onSave={()=>save('employees',site.employees)} busy={busy}/><MemberRolesPanel site={site} setSite={setSite} lang={lang} onSave={save} busy={busy} membership={membership}/></>}
      {tab==='payments'&&<><Payments site={site} setSite={setSite} lang={lang} onSave={()=>save('paymentRules',site.paymentRules)} busy={busy} setError={setError} canConnect={['owner','admin'].includes(membership?.role)}/><PaymentLinksPanel siteId={site.siteId} siteSlug={site.slug} lang={lang}/><PayoutsPanel siteId={site.siteId} lang={lang}/><ReceiptsPanel siteId={site.siteId} lang={lang}/></>}
      {tab==='pos'&&<PosPanel site={site} lang={lang} onSaleComplete={()=>loadCommerce().catch(()=>{})}/>}
      {tab==='marketing'&&<><MarketingPanel site={site} lang={lang}/><ReviewAutomationPanel site={site} lang={lang} onSave={save} busy={busy}/></>}
      {tab==='analytics'&&<>{['owner','admin'].includes(membership?.role)&&<BusinessAccountingPanel siteId={site.siteId} employees={site.employees} catalog={site.catalog} lang={lang} initialMode="expense"/>}<AnalyticsPanel commerce={commerce} lang={lang} siteId={site.siteId} stripeConnected={Boolean(site.paymentRules?.methods?.stripe&&site.paymentRules?.stripeConnectedAccountId)}/></>}
      {tab==='integrations'&&<><section className="ca-panel"><h2>ChatGPT</h2><p>{lang==='es'?'Consulta tu negocio y prepara cambios para aprobarlos en WebFactory.':'Read business information and prepare changes for approval in WebFactory.'}</p><a className="btn secondary" href="/chatgpt">{lang==='es'?'Administrar conexión':'Manage connection'}</a></section><CalendarPanel site={site} setSite={setSite} lang={lang} calendars={calendars} configured={googleConfigured} onSave={()=>save('employees',site.employees)} busy={busy}/><IntegrationManagementPanel site={site} setSite={setSite} lang={lang} membership={membership}/></>}
      {tab==='appearance'&&<PortalAppearance lang={lang} appearance={appearance}/>}
      {tab==='security'&&<MfaSettings lang={lang} allowDisable/>}
      {tab==='settings'&&<><SettingsPanel site={site} lang={lang} onSave={save} busy={busy}/><AccountLifecyclePanel site={site} lang={lang} membership={membership} onPageDeleted={async()=>{setSite(null);setSites([]);await loadSites()}} onAccountDeleted={async()=>{await logout();setUser(null);setSite(null);setSites([])}}/></>}
      {tab==='billing'&&<BillingPanel site={site} billing={billing} lang={lang} busy={busy} setBusy={setBusy} setError={setError}/>}
    </section>
  </main></PortalPanelProvider>
}

function LocationEditor({site,lang,onSave,busy}:{site:ClientSite;lang:Language;onSave:(rows:any[])=>void;busy:boolean}){const es=lang==='es';const [rows,setRows]=useState<any[]>(site.business.locations||[]);useUnsavedChanges(rows,site.revision,setRows,lang,site.business.locations||[]);useEffect(()=>setRows(site.business.locations||[]),[site.revision]);const patch=(index:number,key:string,value:string)=>setRows(current=>current.map((row,i)=>i===index?{...row,[key]:value}:row));const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];const patchHours=(index:number,day:string,key:string,value:any)=>setRows(current=>current.map((row,i)=>i===index?{...row,hours:{...(row.hours||{}),[day]:{enabled:false,open:'09:00',close:'17:00',...(row.hours?.[day]||{}),[key]:value}}}:row));const add=()=>setRows(current=>[...current,{id:uid('location'),name:'',address:'',phone:'',mapsUrl:'',hours:{},active:true}]);return <Panel title={es?'Sucursales':'Locations'} text={es?'Añade localidades y sus direcciones de Google Maps. Asigna los empleados desde Empleados.':'Add branch locations and their Google Maps addresses. Assign employees from Employees.'}><div className="ca-actions"><button onClick={add}>{es?'+ Añadir sucursal':'+ Add location'}</button><Save busy={busy} onClick={()=>onSave(rows)} lang={lang}/></div><div className="ca-list">{rows.map((row,index)=><article key={row.id}><header><strong>{row.name|| (es?'Nueva sucursal':'New location')}</strong><button onClick={()=>setRows(current=>current.filter((_,i)=>i!==index))}>{es?'Eliminar':'Remove'}</button></header><div className="ca-grid"><label>{es?'Nombre':'Name'}<input value={row.name||''} onChange={e=>patch(index,'name',e.target.value)}/></label><label>{es?'Teléfono':'Phone'}<input value={row.phone||''} onChange={e=>patch(index,'phone',e.target.value)}/></label><label className="wide">{es?'Dirección':'Address'}<input value={row.address||''} onChange={e=>patch(index,'address',e.target.value)}/></label><label className="wide">Google Maps URL<input value={row.mapsUrl||''} onChange={e=>patch(index,'mapsUrl',e.target.value)} placeholder="https://maps.google.com/..."/></label><fieldset className="wide"><legend>{es?'Horario de esta sucursal':'Location hours'}</legend>{weekdays.map(day=>{const hours=row.hours?.[day]||{enabled:false,open:'09:00',close:'17:00'};return <div className="ca-location-hours" key={day}><b>{day}</b><label className="check"><input type="checkbox" checked={Boolean(hours.enabled)} onChange={e=>patchHours(index,day,'enabled',e.target.checked)}/>{es?'Abierto':'Open'}</label><input aria-label={`${day} open`} type="time" value={hours.open} onChange={e=>patchHours(index,day,'open',e.target.value)}/><input aria-label={`${day} close`} type="time" value={hours.close} onChange={e=>patchHours(index,day,'close',e.target.value)}/></div>})}</fieldset></div></article>)}</div></Panel>}

function Overview({site,commerce,lang,onSave,busy}:{site:ClientSite;commerce:{orders:Transaction[];bookings:Transaction[]};lang:Language;onSave:(v:any)=>void;busy:boolean}){const [value,setValue]=useState(site.business);useUnsavedChanges(value,site.revision,setValue,lang,site.business);useEffect(()=>setValue(site.business),[site.revision]);const plan=site.servicePlan;const labels=lang==='es'?{service:'Servicio WebFactory',serviceText:'Estado del acceso y la modalidad comercial de este website.',mode:'Modalidad actual',subscription:'Suscripción',subscriptionMode:'Plan de suscripción',complimentary:'Acceso exclusivo de cortesía',active:'Activa',inactive:'No activada',business:'Información del negocio',businessText:'Estos cambios aparecen en el website después de guardar.',name:'Nombre',category:'Categoría',description:'Descripción',template:'Template base',custom:'Custom',viewTemplate:'Ver Template ↗'}:{service:'WebFactory service',serviceText:'Access status and commercial model for this website.',mode:'Current model',subscription:'Subscription',subscriptionMode:'Subscription plan',complimentary:'Exclusive complimentary access',active:'Active',inactive:'Not active',business:'Business information',businessText:'These changes appear on the website after saving.',name:'Name',category:'Category',description:'Description',template:'Base Template',custom:'Custom',viewTemplate:'View Template ↗'};const mode=plan?.billingModel==='complimentary'?labels.complimentary:labels.subscriptionMode;const accessActive=['active','trialing','trial','complimentary'].includes(plan?.subscriptionStatus||'');return <><Panel title={labels.service} text={labels.serviceText}><dl className="ca-service-plan"><div><dt>Plan</dt><dd>{plan?.name||'WebFactory Commerce Platform'}</dd></div><div><dt>{labels.mode}</dt><dd>{mode}</dd></div><div><dt>{labels.subscription}</dt><dd>{accessActive?labels.active:labels.inactive}</dd></div><div><dt>Website</dt><dd>{site.status.replaceAll('_',' ')}</dd></div><div><dt>{labels.template}</dt><dd>{site.design?.mode==='template_base'?(site.design.templateName||site.design.templateCategory||site.design.templateSlug):labels.custom}{site.design?.templateRoute&&<><br/><a href={site.design.templateRoute} target="_blank" rel="noreferrer">{labels.viewTemplate}</a></>}</dd></div></dl></Panel><Panel title={lang==='es'?'Rediseña tu website':'Redesign your website'} text={lang==='es'?'Cambia el diseño, el template, la marca y la categoría de tu negocio desde Builder.':'Change your design, template, brand and business category in Builder.'}>{accessActive?<a className="ca-primary-link" href={`/builder?edit=${encodeURIComponent(site.siteId)}`}>{lang==='es'?'Abrir Builder para rediseñar ↗':'Open Builder to redesign ↗'}</a>:<p>{lang==='es'?'Activa tu suscripción para rediseñar la página.':'Activate your subscription to redesign the website.'}</p>}</Panel><Panel title={labels.business} text={labels.businessText}><div className="ca-grid"><label>Business name · English<input value={value.nameEn||value.name||''} onChange={e=>setValue({...value,name:e.target.value,nameEn:e.target.value})}/></label><label>Nombre del negocio · Español<input value={value.nameEs||''} onChange={e=>setValue({...value,nameEs:e.target.value})}/></label>{[['category',labels.category],['email','Email'],['phone','Phone'],['whatsapp','WhatsApp'],['instagram','Instagram'],['mapsUrl','Google Maps URL']].map(([key,label])=><label key={key}>{label}<input value={value[key]||''} onChange={e=>setValue({...value,[key]:e.target.value})}/></label>)}<label className="wide">Business description · English<textarea rows={5} value={value.descriptionEn||value.description||''} onChange={e=>setValue({...value,description:e.target.value,descriptionEn:e.target.value})}/></label><label className="wide">Descripción del negocio · Español<textarea rows={5} value={value.descriptionEs||''} onChange={e=>setValue({...value,descriptionEs:e.target.value})}/></label></div>{(['privacy','terms','refund'] as const).map(key=><label className="wide" key={key}>{key==='privacy'?(lang==='es'?'Privacidad del negocio':'Business privacy'):key==='terms'?(lang==='es'?'Términos del negocio':'Business terms'):(lang==='es'?'Reembolsos y cancelaciones':'Refunds and cancellations')}<textarea rows={5} maxLength={12000} value={value.policies?.[key]||''} onChange={e=>setValue({...value,policies:{...value.policies,[key]:e.target.value}})}/></label>)}<Save busy={busy} onClick={()=>onSave(value)} lang={lang}/></Panel></>}

function BillingPanel({site,billing,lang,busy,setBusy,setError}:{site:ClientSite;billing:BillingInfo|null;lang:Language;busy:boolean;setBusy:(v:boolean)=>void;setError:(v:string)=>void}){
  const es=lang==='es'
  const [renewalAccepted,setRenewalAccepted]=useState(false)
  const [canceled,setCanceled]=useState(false)
  const [cancellationEnd,setCancellationEnd]=useState('')
  useEffect(()=>{setRenewalAccepted(false);setCanceled(false);setCancellationEnd('')},[site.siteId])
  const status=site.servicePlan?.subscriptionStatus||''
  const startTrial=async()=>{
    setBusy(true);setError('')
    try{
      await api('/.netlify/functions/start-client-trial',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({siteId:site.siteId})})
      location.reload()
    }catch(e){setError(e instanceof Error?e.message:(es?'No se pudo iniciar la prueba.':'The trial could not be started.'));setBusy(false)}
  }
  const choose=async(interval:'monthly'|'annual')=>{
    setBusy(true);setError('')
    try{
      const result=await api('/.netlify/functions/create-subscription-checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({siteId:site.siteId,interval,renewalAccepted,consentVersion:'2026-10-02'})})
      location.assign(result.url)
    }catch(e){setError(e instanceof Error?e.message:(es?'No se pudo abrir la suscripción.':'The subscription checkout could not be opened.'));setBusy(false)}
  }
  const cancelRenewal=async()=>{
    if(!window.confirm(es?'¿Detener futuras renovaciones? Conservarás el acceso hasta finalizar el periodo pagado.':'Stop future renewals? You will keep access through the paid period.'))return
    setBusy(true);setError('')
    try{
      const result=await api('/.netlify/functions/cancel-subscription-renewal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({siteId:site.siteId})})
      setCanceled(true);setCancellationEnd(result.currentPeriodEnd||'')
    }catch(e){setError(e instanceof Error?e.message:(es?'No se pudo cancelar la renovación.':'Renewal could not be canceled.'))}finally{setBusy(false)}
  }
  const ends=billing?.entitlement.trialEndsAt||site.servicePlan?.trialEndsAt||''
  const remaining=ends?Math.max(0,Date.parse(ends)-Date.now()):0
  const days=Math.ceil(remaining/86400000)
  const active=['active','trialing'].includes(status)
  const complimentary=site.servicePlan?.billingModel==='complimentary'
  return <Panel title={es?'Plan WebFactory':'WebFactory Plan'} text={es?'La prueba gratuita no solicita tarjeta ni genera cargos automáticos.':'The free trial does not require a card or create automatic charges.'}>
    {complimentary?<div className="ca-success">{es?'Tienes acceso exclusivo de cortesía a todos los servicios de WebFactory. Este acceso no tiene fecha de vencimiento ni requiere suscripción.':'You have exclusive complimentary access to all WebFactory services. This access does not expire and requires no subscription.'}</div>:<>
      {status==='not_started'&&<div className="ca-trial-start"><strong>{es?'Tu website está listo.':'Your website is ready.'}</strong><span>{es?'Inicia tus 7 días gratis cuando estés preparado para publicarlo.':'Start your free 7-day trial when you are ready to publish it.'}</span><button disabled={busy} onClick={startTrial}>{es?'Iniciar 7 días gratis':'Start 7-day free trial'}</button></div>}
      {status==='trial'&&<div className="ca-warning">{es?`Prueba gratuita de 7 días: quedan aproximadamente ${days} día(s). Al vencer, el website se ocultará hasta seleccionar un plan.`:`7-day free trial: approximately ${days} day(s) remain. When it expires, the website will be hidden until a plan is selected.`}</div>}
      {active?<div className="ca-success">{es?'Tu suscripción está activa y el website permanece publicado.':'Your subscription is active and the website remains published.'}</div>:status!=='not_started'&&<div className="ca-plans"><article><small>{es?'MENSUAL':'MONTHLY'}</small><strong>$30</strong><span>{es?'USD cada mes · $360 al año':'USD each month · $360 per year'}</span><button disabled={busy||!billing?.readiness.ready||!renewalAccepted} onClick={()=>choose('monthly')}>{es?'Seleccionar mensual':'Select monthly'}</button></article><article><small>{es?'ANUAL':'ANNUAL'}</small><strong>$350</strong><span>{es?'USD cada año · ahorra $10':'USD each year · save $10'}</span><button disabled={busy||!billing?.readiness.ready||!renewalAccepted} onClick={()=>choose('annual')}>{es?'Seleccionar anual':'Select annual'}</button></article></div>}
      {!active&&status!=='not_started'&&<label className="check ca-renewal-consent"><input type="checkbox" checked={renewalAccepted} onChange={e=>setRenewalAccepted(e.target.checked)}/><span>{es?'Acepto que el plan elegido renueva automáticamente: $30 USD cada mes o $350 USD cada año, hasta cancelar. Puedo detener renovaciones en Plan WebFactory y conservar el periodo pagado.':'I agree the selected plan renews automatically: $30 USD each month or $350 USD each year, until canceled. I can stop renewals in WebFactory Plan and keep the paid period.'} <a href="/terms" target="_blank" rel="noreferrer">{es?'Términos':'Terms'}</a> · <a href="/refund-policy" target="_blank" rel="noreferrer">{es?'Reembolsos':'Refunds'}</a></span></label>}
      {(active||status==='past_due')&&<div className="ca-actions">{site.servicePlan?.cancelAtPeriodEnd||canceled?<p role="status">{es?'Renovación cancelada. El acceso continúa hasta finalizar el periodo pagado.':'Renewal canceled. Access continues through the paid period.'} {(cancellationEnd||site.servicePlan?.currentPeriodEnd)&&new Date(cancellationEnd||site.servicePlan!.currentPeriodEnd).toLocaleDateString(es?'es-PR':'en-US')}</p>:<button disabled={busy} onClick={cancelRenewal}>{es?'Cancelar futuras renovaciones':'Cancel future renewals'}</button>}</div>}
      {billing&&!billing.readiness.ready&&status!=='not_started'&&<p className="ca-note">{es?'Las ofertas todavía están en preparación y no pueden generar cargos.':'The plans are still being prepared and cannot create charges.'}</p>}
    </>}
    <p className="ca-note">{es?'WebFactory no cobra comisión sobre las ventas del negocio. La suscripción cubre el uso continuo de la plataforma, hosting, portal y actualizaciones.':'WebFactory does not charge a commission on business sales. The subscription covers continued platform use, hosting, the portal, and updates.'}</p>
  </Panel>
}

function CatalogEditor({site,setSite,lang,onSave,busy}:{site:ClientSite;setSite:(s:ClientSite)=>void;lang:Language;onSave:()=>void;busy:boolean}){const es=lang==='es';useUnsavedChanges(site.catalog,site.revision,original=>setSite({...site,catalog:original}),lang);const update=(i:number,patch:Partial<CatalogItem>)=>setSite({...site,catalog:site.catalog.map((x,n)=>n===i?{...x,...patch}:x)});const add=()=>site.catalog.length<100&&setSite({...site,catalog:[...site.catalog,{id:uid('item'),type:'product',name:'New item',nameEn:'New item',nameEs:'',description:'',descriptionEn:'',descriptionEs:'',price:0,active:true,inventory:null,requiresAppointment:false,duration:30,bufferMinutes:0}]});return <Panel title={es?'Productos y servicios':'Products and services'} text={es?`${site.catalog.length} de 100 artículos. Completa English y Español para que el website cambie todo el contenido.`:`${site.catalog.length} of 100 items. Complete English and Spanish so the website can switch all customer content.`}><div className="ca-actions"><button onClick={add}>{es?'+ Añadir':'+ Add'}</button><Save busy={busy} onClick={onSave} lang={lang}/></div><div className="ca-list">{site.catalog.length===0&&<p role="status">{es?'Añade tu primer producto o servicio con el botón «+ Añadir».':'Add your first product or service using “+ Add”.'}</p>}{site.catalog.map((item,i)=><article key={item.id}><header><strong>{(es?(item.nameEs||item.nameEn||item.name):(item.nameEn||item.name||item.nameEs))|| (es?'Sin nombre':'Untitled')}</strong><button onClick={()=>{if(confirm(es?`¿Eliminar ${item.name} del catálogo al guardar?`:`Remove ${item.name} from the catalog when saved?`))setSite({...site,catalog:site.catalog.filter((_,n)=>n!==i)})}}>{es?'Eliminar':'Delete'}</button></header><div className="ca-grid compact"><label>Name · English<input value={item.nameEn||item.name||''} onChange={e=>update(i,{name:e.target.value,nameEn:e.target.value})}/></label><label>Nombre · Español<input value={item.nameEs||''} onChange={e=>update(i,{nameEs:e.target.value})}/></label><label>{es?'Tipo':'Type'}<select value={item.type} onChange={e=>update(i,{type:e.target.value as any,requiresAppointment:e.target.value==='service'&&item.requiresAppointment})}><option value="product">{es?'Producto':'Product'}</option><option value="service">{es?'Servicio':'Service'}</option></select></label><label>{es?'Precio USD':'Price USD'}<input type="number" min="0" step="0.01" value={item.price} onChange={e=>update(i,{price:Number(e.target.value)})}/></label>{item.type==='product'&&<label className="check"><input type="checkbox" checked={Boolean(item.trackInventory)} onChange={e=>update(i,{trackInventory:e.target.checked,inventory:e.target.checked?(item.inventory??0):item.inventory})}/>{es?'Controlar existencias':'Track stock'}</label>}{item.type==='product'&&<label>{es?'Inventario':'Inventory'}<input type="number" min="0" value={item.inventory??''} placeholder={es?'Sin límite':'Unlimited'} onChange={e=>update(i,{inventory:e.target.value===''?null:Number(e.target.value)})}/></label>}{item.type==='service'&&<><label>{es?'Duración (min)':'Duration (min)'}<input type="number" value={item.duration} onChange={e=>update(i,{duration:Number(e.target.value)})}/></label><label>{es?'Margen (min)':'Buffer (min)'}<input type="number" value={item.bufferMinutes} onChange={e=>update(i,{bufferMinutes:Number(e.target.value)})}/></label><label className="check"><input type="checkbox" checked={item.requiresAppointment} onChange={e=>update(i,{requiresAppointment:e.target.checked})}/> {es?'Requiere cita':'Requires booking'}</label></>}<label className="check"><input type="checkbox" checked={item.active} onChange={e=>update(i,{active:e.target.checked})}/> {es?'Visible':'Visible'}</label><div className="wide"><CatalogPhoto siteId={site.siteId} item={item} lang={lang} onUploaded={imageAssetKey=>update(i,{imageAssetKey})}/></div><CatalogPresentationFields item={item} onChange={patch=>update(i,patch)} lang={lang}/><label className="wide">Description · English<textarea value={item.descriptionEn||item.description||''} onChange={e=>update(i,{description:e.target.value,descriptionEn:e.target.value})}/></label><label className="wide">Descripción · Español<textarea value={item.descriptionEs||''} onChange={e=>update(i,{descriptionEs:e.target.value})}/></label></div></article>)}</div></Panel>}

function CatalogPhoto({siteId,item,lang,onUploaded}:{siteId:string;item:CatalogItem;lang:Language;onUploaded:(key:string)=>void}){
 const [uploading,setUploading]=useState(false);const [error,setError]=useState('')
 const upload=async(file?:File)=>{if(!file)return;setUploading(true);setError('');try{const form=new FormData();form.append('siteId',siteId);form.append('file',file);const result=await api('/.netlify/functions/client-asset',{method:'POST',body:form});onUploaded(result.assetKey)}catch(e){setError(e instanceof Error?e.message:'Upload failed.')}finally{setUploading(false)}}
 return <div><label>{lang==='es'?'Foto del producto o servicio':'Product or service photo'}<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" disabled={uploading} onChange={event=>void upload(event.target.files?.[0])}/></label>{uploading&&<p role="status">{lang==='es'?'Subiendo foto…':'Uploading photo…'}</p>}{item.imageAssetKey&&<><img src={`/.netlify/functions/client-asset?siteId=${encodeURIComponent(siteId)}&key=${encodeURIComponent(item.imageAssetKey)}`} alt={item.name} style={{width:160,height:110,objectFit:'cover',borderRadius:12,marginTop:10}}/><p>{lang==='es'?'Foto lista. Guarda los cambios para publicarla.':'Photo ready. Save changes to publish it.'}</p></>}{error&&<p role="alert">{error}</p>}</div>
}

function TeamEditor({site,setSite,lang,onSave,busy}:{site:ClientSite;setSite:(s:ClientSite)=>void;lang:Language;onSave:()=>void;busy:boolean}){const es=lang==='es';useUnsavedChanges(site.employees,site.revision,original=>setSite({...site,employees:original}),lang);const update=(i:number,p:Partial<Employee>)=>setSite({...site,employees:site.employees.map((x,n)=>n===i?{...x,...p}:x)});const serviceName=(service:CatalogItem)=>es?(service.nameEs||service.nameEn||service.name):(service.nameEn||service.name||service.nameEs);return <Panel title={es?'Equipo':'Team'} text={es?'Los nombres propios se mantienen y los roles pueden tener versión English y Español.':'Names stay the same while roles can have separate English and Spanish versions.'}><div className="ca-actions"><button onClick={()=>setSite({...site,employees:[...site.employees,{id:uid('employee'),name:'New employee',role:'Professional',roleEn:'Professional',roleEs:'',active:true,serviceIds:[],calendarId:'',dailyLimit:8,schedule:{},timeOff:[]}]})}>{es?'+ Añadir':'+ Add'}</button><Save busy={busy} onClick={onSave} lang={lang}/></div><div className="ca-list">{site.employees.length===0&&<p role="status">{es?'Añade tu primer empleado desde Equipo.':'Add your first employee from Team.'}</p>}{site.employees.map((employee,i)=><article key={employee.id}><header><input value={employee.name} onChange={e=>update(i,{name:e.target.value})}/><button onClick={()=>{if(confirm(es?`¿Eliminar a ${employee.name} del equipo al guardar?`:`Remove ${employee.name} from the team when saved?`))setSite({...site,employees:site.employees.filter((_,n)=>n!==i)})}}>{es?'Eliminar':'Delete'}</button></header><div className="ca-grid compact"><label>Role · English<input value={employee.roleEn||employee.role||''} onChange={e=>update(i,{role:e.target.value,roleEn:e.target.value})}/></label><label>Rol · Español<input value={employee.roleEs||''} onChange={e=>update(i,{roleEs:e.target.value})}/></label><label>{es?'Límite diario':'Daily limit'}<input type="number" min="1" value={employee.dailyLimit} onChange={e=>update(i,{dailyLimit:Number(e.target.value)})}/></label><label className="check"><input type="checkbox" checked={employee.active} onChange={e=>update(i,{active:e.target.checked})}/> {es?'Activo':'Active'}</label><fieldset className="wide"><legend>{es?'Servicios':'Services'}</legend>{site.catalog.filter(x=>x.type==='service').map(service=><label className="check" key={service.id}><input type="checkbox" checked={employee.serviceIds.includes(service.id)} onChange={e=>update(i,{serviceIds:e.target.checked?[...employee.serviceIds,service.id]:employee.serviceIds.filter(id=>id!==service.id)})}/>{serviceName(service)}</label>)}</fieldset>{(site.business.locations||[]).length>0&&<fieldset className="wide"><legend>{es?'Sucursales asignadas':'Assigned locations'}</legend>{site.business.locations.map((location:any)=><label className="check" key={location.id}><input type="checkbox" checked={(employee.locationIds||[]).includes(location.id)} onChange={e=>update(i,{locationIds:e.target.checked?[...(employee.locationIds||[]),location.id]:(employee.locationIds||[]).filter(id=>id!==location.id)})}/>{location.name}</label>)}</fieldset>}</div></article>)}</div></Panel>}

function HoursEditor({site,setSite,lang,onSave,busy}:{site:ClientSite;setSite:(s:ClientSite)=>void;lang:Language;onSave:()=>void;busy:boolean}){const es=lang==='es';useUnsavedChanges(site.hours,site.revision,original=>setSite({...site,hours:original}),lang);const dayNames:Record<string,string>={monday:es?'Lunes':'Monday',lunes:es?'Lunes':'Monday',tuesday:es?'Martes':'Tuesday',martes:es?'Martes':'Tuesday',wednesday:es?'Miércoles':'Wednesday','miércoles':es?'Miércoles':'Wednesday',miercoles:es?'Miércoles':'Wednesday',thursday:es?'Jueves':'Thursday',jueves:es?'Jueves':'Thursday',friday:es?'Viernes':'Friday',viernes:es?'Viernes':'Friday',saturday:es?'Sábado':'Saturday','sábado':es?'Sábado':'Saturday',sabado:es?'Sábado':'Saturday',sunday:es?'Domingo':'Sunday',domingo:es?'Domingo':'Sunday'};return <Panel title={es?'Horario general':'Business hours'} text={es?'La disponibilidad real también considera empleado, citas, holds y Google Calendar.':'Real availability also considers employees, bookings, holds and Google Calendar.'}><div className="ca-hours">{Object.entries(site.hours).map(([day,hours])=><article key={day}><b>{dayNames[day.toLowerCase()]||day}</b><label className="check"><input type="checkbox" checked={hours.enabled} onChange={e=>setSite({...site,hours:{...site.hours,[day]:{...hours,enabled:e.target.checked}}})}/>{es?'Abierto':'Open'}</label><input type="time" value={hours.open} onChange={e=>setSite({...site,hours:{...site.hours,[day]:{...hours,open:e.target.value}}})}/><input type="time" value={hours.close} onChange={e=>setSite({...site,hours:{...site.hours,[day]:{...hours,close:e.target.value}}})}/></article>)}</div><Save busy={busy} onClick={onSave} lang={lang}/></Panel>}

function Payments({site,setSite,lang,onSave,busy,setError,canConnect}:{site:ClientSite;setSite:(s:ClientSite)=>void;lang:Language;onSave:()=>void;busy:boolean;setError:(s:string)=>void;canConnect:boolean}){const es=lang==='es';useUnsavedChanges(site.paymentRules,site.revision,original=>setSite({...site,paymentRules:original}),lang);const p=site.paymentRules||{};return <Panel title={es?'Pagos':'Payments'} text={es?'Los fondos llegan a la cuenta del negocio en el proveedor seleccionado: Stripe o ATH Móvil.':'Funds go to the business account with the selected provider: Stripe or ATH Móvil.'}><StripeConnection site={site} setSite={setSite} lang={lang} canConnect={canConnect}/><AthConnection site={site} setSite={setSite} lang={lang} canConnect={canConnect}/><div className="ca-grid"><label>{es?'Pago de productos':'Product payments'}<select value={p.productPayment||'online'} onChange={e=>setSite({...site,paymentRules:{...p,productPayment:e.target.value}})}><option value="online">Online</option><option value="in_person">{es?'Presencial':'In person'}</option></select></label><label>{es?'Pago de citas':'Booking payments'}<select value={p.bookingPayment||'full'} onChange={e=>setSite({...site,paymentRules:{...p,bookingPayment:e.target.value}})}><option value="full">{es?'Completo':'Full payment'}</option><option value="deposit">{es?'Depósito':'Deposit'}</option><option value="in_person">{es?'Presencial':'In person'}</option></select></label>{p.bookingPayment==='deposit'&&<label>{es?'Depósito %':'Deposit %'}<select value={p.bookingDepositPercent||25} onChange={e=>setSite({...site,paymentRules:{...p,bookingDepositPercent:Number(e.target.value)}})}>{[10,20,25,30,50].map(x=><option key={x}>{x}</option>)}</select></label>}</div><Save busy={busy} onClick={onSave} lang={lang}/><p className="ca-note">{es?'Identidad, banco, impuestos, disputas sensibles y seguridad se completan en pantallas oficiales de Stripe cuando sea requerido.':'Identity, banking, taxes, sensitive disputes and security are completed on official Stripe screens when required.'}</p></Panel>}

function CalendarPanel({site,setSite,lang,calendars,configured,onSave,busy}:{site:ClientSite;setSite:(s:ClientSite)=>void;lang:Language;calendars:Array<{id:string;summary:string;primary:boolean}>;configured:boolean;onSave:()=>void;busy:boolean}){const es=lang==='es';useUnsavedChanges(site.employees,site.revision,original=>setSite({...site,employees:original}),lang);return <Panel title="Google Calendar" text={es?'Conecta Google Calendar por separado del email del negocio y asigna un calendario a cada empleado para sincronizar eventos y conflictos.':'Connect Google Calendar separately from business email and assign a calendar to each employee to synchronize events and conflicts.'}>{!configured?<div className="ca-warning">{es?'La aplicación Google OAuth todavía necesita sus credenciales privadas de producción.':'The Google OAuth application still needs its private production credentials.'}</div>:!site.googleCalendar?.connected?<a className="ca-primary-link" href={`/.netlify/functions/google-calendar-start?siteId=${encodeURIComponent(site.siteId)}`}>{es?'Conectar Google Calendar':'Connect Google Calendar'}</a>:<><div className="ca-success">{es?'Google Calendar conectado.':'Google Calendar connected.'}</div><div className="ca-list">{site.employees.length===0&&<p role="status">{es?'Añade tu primer empleado desde Equipo.':'Add your first employee from Team.'}</p>}{site.employees.map((employee,i)=><article key={employee.id}><strong>{employee.name}</strong><label>{es?'Calendario':'Calendar'}<select value={employee.calendarId||''} onChange={e=>setSite({...site,employees:site.employees.map((x,n)=>n===i?{...x,calendarId:e.target.value}:x)})}><option value="">{es?'Sin asignar':'Unassigned'}</option>{calendars.map(calendar=><option value={calendar.id} key={calendar.id}>{calendar.summary}{calendar.primary?(es?' (principal)':' (primary)'):''}</option>)}</select></label></article>)}</div><Save busy={busy} onClick={onSave} lang={lang}/></>}</Panel>}

function Commerce({records,lang,onAction,busy}:{records:{orders:Transaction[];bookings:Transaction[]};lang:Language;onAction:(r:Transaction,a:string)=>void;busy:boolean}){const es=lang==='es';const all=[...records.bookings,...records.orders].sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));return <Panel title={es?'Órdenes y citas':'Orders and bookings'} text={es?'Los pagos online se confirman en el servidor con su proveedor: Stripe o ATH Móvil.':'Online payments are confirmed by the server with their provider: Stripe or ATH Móvil.'}><div className="ca-transactions">{all.length===0?<p>{es?'No hay transacciones todavía.':'There are no transactions yet.'}</p>:all.map(record=><article key={record.transactionId}><div><small>{record.kind==='booking'?(es?'CITA':'BOOKING'):(es?'ORDEN':'ORDER')}</small><strong>{record.customer.name}</strong><span>{record.transactionId}</span></div><div><b>{money(record.amountTotal)}</b><span>{record.paymentStatus} · {record.status}</span>{record.start&&<time>{new Date(record.start).toLocaleString(es?'es-PR':'en-US')}</time>}</div><nav>{record.paymentStatus==='due'&&<button disabled={busy} onClick={()=>onAction(record,'mark_paid')}>{es?'Marcar pagado':'Mark paid'}</button>}{record.paymentProvider!=='ath_movil'&&record.paymentStatus==='paid'&&Number(record.refundedAmount||0)<Number(record.amountTotal||0)&&<button disabled={busy} onClick={()=>onAction(record,'refund')}>{record.refundedAmount?(es?'Reembolsar restante':'Refund remaining'):(es?'Reembolsar':'Refund')}</button>}{record.kind==='booking'&&record.status!=='cancelled'&&<button disabled={busy} onClick={()=>onAction(record,'cancel')}>{es?'Cancelar':'Cancel'}</button>}</nav></article>)}</div></Panel>}

function Panel({title,text,children}:{title:string;text:string;children:React.ReactNode}){return <PortalPanel className="ca-panel"><header><h2>{title}</h2><p>{text}</p></header>{children}</PortalPanel>}
function Save({busy,onClick,lang='es'}:{busy:boolean;onClick:()=>void;lang?:Language}){return <button className="ca-save" aria-busy={busy} disabled={busy} onClick={onClick}>{busy?(lang==='es'?'Guardando…':'Saving…'):(lang==='es'?'Guardar cambios':'Save changes')}</button>}
